/**
 * Generates supabase/tests/split_vectors.test.sql from shared/test-vectors.json,
 * so pgTAP checks the SQL split functions against exactly the same cases as Vitest.
 *
 * pgTAP runs inside the database container and cannot read files outside
 * supabase/tests, so the vectors are embedded in the generated file.
 * Run `npm run gen:sql-vectors` after changing the vectors.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const VECTORS_PATH = 'shared/test-vectors.json';
export const SQL_TESTS_PATH = 'supabase/tests/split_vectors.test.sql';

interface Vectors {
  household: unknown[];
  household_invalid: unknown[];
  people: unknown[];
  people_invalid: unknown[];
}

/** Static checks after the vectors: shares add up for every total from 1 cent to $20. */
const INVARIANT_TESTS = 4;

export function renderSqlVectorTests(json: string): string {
  const vectors = JSON.parse(json) as Vectors;
  const planned =
    vectors.household.length +
    vectors.household_invalid.length +
    vectors.people.length +
    vectors.people_invalid.length +
    INVARIANT_TESTS;
  const compact = JSON.stringify(vectors);
  if (compact.includes('$vectors$')) throw new Error('Vectors cannot contain $vectors$');

  return `-- GENERATED by scripts/sql-vectors.ts from ${VECTORS_PATH}. Do not edit by hand.
-- Run \`npm run gen:sql-vectors\` after changing the vectors.
begin;
select plan(${String(planned)});

create temp table vectors on commit drop as
  select $vectors$${compact}$vectors$::jsonb as v;

-- Household splits
select is(
  (select array[s.other_cents, s.payer_cents]
     from private.split_household((t ->> 'total_cents')::numeric, t ->> 'split_type',
                                  (t ->> 'split_num')::numeric, (t ->> 'split_den')::numeric) s),
  array[(t -> 'expected' ->> 'other_cents')::integer, (t -> 'expected' ->> 'payer_cents')::integer],
  'household: ' || (t ->> 'name'))
from vectors, jsonb_array_elements(v -> 'household') with ordinality as x(t, n)
order by n;

select throws_ok(
  format('select * from private.split_household(%s, %L, %s, %s)',
         t ->> 'total_cents', t ->> 'split_type',
         coalesce(t ->> 'split_num', 'null'), coalesce(t ->> 'split_den', 'null')),
  '22023', t ->> 'error', 'household rejects: ' || (t ->> 'name'))
from vectors, jsonb_array_elements(v -> 'household_invalid') with ordinality as x(t, n)
order by n;

-- People splits
select is(
  (select jsonb_object_agg(s.party_id, s.share_cents)
     from private.split_people((t ->> 'total_cents')::numeric, t ->> 'split_type', t -> 'parties') s),
  t -> 'expected',
  'people: ' || (t ->> 'name'))
from vectors, jsonb_array_elements(v -> 'people') with ordinality as x(t, n)
order by n;

select throws_ok(
  format('select * from private.split_people(%s, %L, %L::jsonb)',
         t ->> 'total_cents', t ->> 'split_type', t -> 'parties'),
  '22023', t ->> 'error', 'people rejects: ' || (t ->> 'name'))
from vectors, jsonb_array_elements(v -> 'people_invalid') with ordinality as x(t, n)
order by n;

-- Invariants: shares always add up to the total and are never negative.
select is(
  (select count(*)::integer
     from generate_series(1, 2000) as total,
          unnest(array['third', 'half', 'fraction', 'percent']) as split_type,
          lateral private.split_household(total, split_type,
            case split_type when 'fraction' then 3 when 'percent' then 3750 end,
            case split_type when 'fraction' then 7 end) s
    where s.other_cents + s.payer_cents <> total or s.other_cents < 0 or s.payer_cents < 0),
  0, 'household shares add up for every total from 1 to 2000 cents');

select is(
  (select count(*)::integer
     from generate_series(1, 2000) as total
    where (select sum(share_cents) from private.split_people(total, 'weights',
             '[{"id":"a","sort_order":1,"value":3},{"id":"b","sort_order":2,"value":5},{"id":"c","sort_order":3,"value":11}]'))
          <> total),
  0, 'people weight shares add up for every total from 1 to 2000 cents');

select is(
  (select array_agg(party_id order by ord)
     from private.split_people(100, 'equal', '[{"id":"x","sort_order":2},{"id":"y","sort_order":1}]')
          with ordinality as s(party_id, share_cents, ord)),
  array['y', 'x'],
  'people shares come back in sort order');

select throws_ok(
  $$select * from private.split_household(100, 'equal', null, null)$$,
  '22023', 'invalid_split_type', 'household rejects a people split type');

select * from finish();
rollback;
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(SQL_TESTS_PATH, renderSqlVectorTests(readFileSync(VECTORS_PATH, 'utf8')));
  console.log(`Wrote ${SQL_TESTS_PATH}`);
}
